-- =====================================================================
-- H2 建表脚本（h2 profile 专用）
-- 与 PostgreSQL 版 V1__init_schema.sql 结构一致，仅做方言适配：
--   1. 去掉 vector 扩展、COMMENT ON 语句（H2 不支持）
--   2. BIGSERIAL → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   3. jsonb → TEXT（sources_json 在 H2 里按普通字符串存储）
--   4. vector_store 表不建：h2 模式走内存向量库
-- 生产环境请使用 db/migration/V1__init_schema.sql（Flyway 管理）
-- =====================================================================

CREATE TABLE IF NOT EXISTS sys_user
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username     VARCHAR(64)  NOT NULL,
    password     VARCHAR(128) NOT NULL,
    nickname     VARCHAR(64),
    email        VARCHAR(128),
    role         VARCHAR(32)  NOT NULL DEFAULT 'USER',
    status       INTEGER      NOT NULL DEFAULT 1,
    is_deleted   INTEGER      NOT NULL DEFAULT 0,
    gmt_create   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_username ON sys_user (username);

CREATE TABLE IF NOT EXISTS kb_knowledge_base
(
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                 VARCHAR(128)  NOT NULL,
    description          VARCHAR(512),
    owner_id             BIGINT        NOT NULL,
    embedding_model      VARCHAR(64)   NOT NULL DEFAULT 'BAAI/bge-m3',
    embedding_dim        INTEGER       NOT NULL DEFAULT 1024,
    chunk_size           INTEGER       NOT NULL DEFAULT 600,
    chunk_overlap        INTEGER       NOT NULL DEFAULT 80,
    top_k                INTEGER       NOT NULL DEFAULT 5,
    similarity_threshold NUMERIC(4, 3) NOT NULL DEFAULT 0.500,
    doc_count            INTEGER       NOT NULL DEFAULT 0,
    status               INTEGER       NOT NULL DEFAULT 1,
    is_deleted           INTEGER       NOT NULL DEFAULT 0,
    gmt_create           TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_kb_owner ON kb_knowledge_base (owner_id, is_deleted);

CREATE TABLE IF NOT EXISTS kb_document
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kb_id        BIGINT       NOT NULL,
    file_name    VARCHAR(255) NOT NULL,
    file_key     VARCHAR(512) NOT NULL,
    file_size    BIGINT       NOT NULL,
    file_type    VARCHAR(16)  NOT NULL,
    file_md5     VARCHAR(64)  NOT NULL,
    page_count   INTEGER      NOT NULL DEFAULT 0,
    chunk_count  INTEGER      NOT NULL DEFAULT 0,
    parse_status VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    retry_count  INTEGER      NOT NULL DEFAULT 0,
    error_msg    VARCHAR(1024),
    is_deleted   INTEGER      NOT NULL DEFAULT 0,
    gmt_create   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_doc_kb ON kb_document (kb_id, is_deleted);

CREATE TABLE IF NOT EXISTS chat_conversation
(
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kb_id           BIGINT       NOT NULL,
    user_id         BIGINT       NOT NULL,
    title           VARCHAR(128) NOT NULL DEFAULT '新对话',
    message_count   INTEGER      NOT NULL DEFAULT 0,
    last_message_at TIMESTAMP,
    is_deleted      INTEGER      NOT NULL DEFAULT 0,
    gmt_create      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_conv_user ON chat_conversation (user_id);

CREATE TABLE IF NOT EXISTS chat_message
(
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conversation_id   BIGINT      NOT NULL,
    role              VARCHAR(16) NOT NULL,
    content           TEXT        NOT NULL,
    model             VARCHAR(64),
    prompt_tokens     INTEGER     NOT NULL DEFAULT 0,
    completion_tokens INTEGER     NOT NULL DEFAULT 0,
    latency_ms        INTEGER     NOT NULL DEFAULT 0,
    sources_json      TEXT,
    gmt_create        TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_msg_conv ON chat_message (conversation_id);

CREATE TABLE IF NOT EXISTS ai_model_config
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provider     VARCHAR(32)    NOT NULL,
    model_name   VARCHAR(64)    NOT NULL,
    model_type   VARCHAR(16)    NOT NULL,
    base_url     VARCHAR(255),
    api_key      VARCHAR(512)   NOT NULL,
    input_price  NUMERIC(10, 6),
    output_price NUMERIC(10, 6),
    is_default   INTEGER        NOT NULL DEFAULT 0,
    status       INTEGER        NOT NULL DEFAULT 1,
    gmt_create   TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS ai_call_log
(
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id           BIGINT         NOT NULL,
    scene             VARCHAR(32)    NOT NULL,
    model             VARCHAR(64)    NOT NULL,
    prompt_tokens     INTEGER        NOT NULL DEFAULT 0,
    completion_tokens INTEGER        NOT NULL DEFAULT 0,
    cost              NUMERIC(12, 6) NOT NULL DEFAULT 0,
    latency_ms        INTEGER        NOT NULL DEFAULT 0,
    is_success        INTEGER        NOT NULL DEFAULT 1,
    error_code        VARCHAR(16),
    trace_id          VARCHAR(64),
    gmt_create        TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_call_user_time ON ai_call_log (user_id);
-- ---------------------------------------------------------------------
-- 分块正文表（混合检索关键词召回）
-- 与生产 V2__init_chunk_table.sql 结构一致，仅做方言适配
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS kb_chunk
(
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kb_id        BIGINT        NOT NULL,
    doc_id       BIGINT        NOT NULL,
    doc_name     VARCHAR(255)  NOT NULL,
    page_no      INTEGER,
    chunk_no     INTEGER       NOT NULL,
    content      CLOB          NOT NULL,
    is_deleted   INTEGER       NOT NULL DEFAULT 0,
    gmt_create   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    gmt_modified TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_chunk_kb_id ON kb_chunk (kb_id);
CREATE INDEX IF NOT EXISTS idx_chunk_doc_id ON kb_chunk (doc_id);